import { SheetBody } from '../../slots/defs/sheetBody';
import { ClaimedTotal } from './ClaimedTotal';
import { TagTotals } from './TagTotals';
import { VoidReasons } from './VoidReasons';

export const contributions = [
  SheetBody.fill({ order: 20, Component: ClaimedTotal }),
  SheetBody.fill({ order: 27, Component: TagTotals }),
  SheetBody.fill({ order: 9.5, Component: VoidReasons }),
];
import { useQuery } from '@tanstack/react-query';
import { gradeOn, listPeople, peopleKey } from '../people/api';
import { claimDue, listRates, ratesKey, sumDues } from '../rates/api';
import { useFloor, useLate } from '../settings/api';
import { useSheetToday } from '../sheet/api';
import { claimsKey, counts, listClaims, listTags, liveClaims, tagsKey, tagsOf, type Claim } from './api';
import { Fig } from '../session/Fig';

/** For every tag ever used on the sheet, its due-total: the due figures of the claims that count (the
 *  live ones, OPEN, PENDING or SETTLED) carrying it, added up (n/a ones skipped); a claim with two tags
 *  counts in both, and a claim counts under its person's tags too (once for a tag both carry). */
export function TagTotals({ sheetId, user }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const used = useQuery({ queryKey: tagsKey(sheetId), queryFn: () => listTags(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const byId = new Map((people.data ?? []).map((p) => [p.id, p]));
  const live = liveClaims(claims.data ?? [], people.data).filter((c) => counts(c) && byId.has(c.personId));
  const carried = (c: Claim) => [...tagsOf(c), ...tagsOf(byId.get(c.personId) ?? { tags: null })];
  const tags = [...new Set([...(used.data ?? []), ...(claims.data ?? []).flatMap(tagsOf),
    ...(people.data ?? []).flatMap(tagsOf)])].sort();
  if (tags.length === 0) return null;
  const dueOf = (tag: string) => sumDues(live.filter((c) => carried(c).includes(tag)).map((c) => {
    const p = byId.get(c.personId)!;
    return claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges);
  }));
  return (
    <p>
      Due by tag{' '}
      {tags.map((t) => (
        <span key={t}>
          {t} <span data-testid={`tag-${t}-due-total`}><Fig>{dueOf(t)}</Fig></span>{' '}
        </span>
      ))}
    </p>
  );
}
import { useQuery } from '@tanstack/react-query';
import { claimsKey, listClaims, liveClaims } from '../claims/api';
import { gradeOn, listPeople, peopleKey, type Person } from '../people/api';
import { useFloor, useLate } from '../settings/api';
import { liveKey, useSheetToday } from '../sheet/api';
import { claimDue, listRates, overdue, ratesKey, trimmedSum } from './api';
import { Fig } from '../session/Fig';

/** The sheet's overdue claims: how many of the claims that count are OPEN past their due-by, and
 *  their due (with its late charge) added up per person, the sheet's total leaving out the single
 *  highest and lowest person's when there are three or more people (`current`: as it is now, even while
 *  shown as of a date). */
export function useOverdue(sheetId: string, user: string, current = false): ReturnType<typeof overdue> {
  const people = useQuery({ queryKey: liveKey(peopleKey(sheetId), current), queryFn: () => listPeople(sheetId, current) });
  const claims = useQuery({ queryKey: liveKey(claimsKey(sheetId), current), queryFn: () => listClaims(sheetId, current) });
  const rates = useQuery({ queryKey: liveKey(ratesKey(sheetId), current), queryFn: () => listRates(sheetId, current) });
  const floor = useFloor(sheetId, current);
  const today = useSheetToday(sheetId, user, current);
  const charges = useLate(sheetId, today, current);
  const byId = new Map<number, Person>((people.data ?? []).map((p) => [p.id, p]));
  const live = liveClaims(claims.data ?? [], people.data).filter((c) => byId.has(c.personId));
  const dueOf = (c: Parameters<typeof claimDue>[0]) => claimDue(c, rates.data, (d) => gradeOn(byId.get(c.personId)!, d), floor, charges);
  const perPerson = (people.data ?? []).map((p) => overdue(live.filter((c) => c.personId === p.id), charges, dueOf).total);
  return { count: overdue(live, charges, dueOf).count, total: trimmedSum(perPerson) };
}

export function Overdue({ sheetId, user }: { sheetId: string; user: string }) {
  const late = useOverdue(sheetId, user);
  return (
    <p>
      Overdue <span data-testid="rollup-overdue-count">{late.count}</span>{' '}
      totalling <span data-testid="rollup-overdue-total"><Fig>{late.total}</Fig></span>
    </p>
  );
}
import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { defineSlot } from '../Slot';

/**
 * The loaded sheet's content. Everything kept per sheet contributes here and is handed the active
 * sheet's id and the signed-in user; its queries go under ['sheet', sheetId, ...].
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
